const source = $json.text;

const sourceFilename = $json.source_filename;
const sourceDirectory = '/files/utility-import';
const sourcePath = $json.source_path;

if (
  typeof sourceFilename !== 'string' ||
  !sourceFilename ||
  sourceFilename.includes('/') ||
  sourceFilename.includes('\\') ||
  /[\x00-\x1f\x7f]/.test(sourceFilename) ||
  !/\.pdf$/i.test(sourceFilename)
) {
  throw new Error('Отсутствует или недопустимо имя PDF');
}

if (sourcePath !== `${sourceDirectory}/${sourceFilename}`) {
  throw new Error('Путь PDF не соответствует его имени');
}

if (typeof source !== 'string' || !source.trim()) {
  throw new Error('Отсутствует текст PDF');
}

// Отделяем основную квитанцию от второго платёжного документа.
const documents = source.split('ПЛАТЕЖНЫЙ ДОКУМЕНТ');

if (documents.length < 2) {
  throw new Error('Не найден основной платёжный документ');
}

const text = documents[1]
  .replace(/[\u00a0\u202f]/g, ' ');

const flat = text.replace(/\s+/g, ' ').trim();

const months = {
  январь: '01',
  февраль: '02',
  март: '03',
  апрель: '04',
  май: '05',
  июнь: '06',
  июль: '07',
  август: '08',
  сентябрь: '09',
  октябрь: '10',
  ноябрь: '11',
  декабрь: '12',
};

function requiredMatch(pattern, label, input = flat) {
  const match = input.match(pattern);

  if (!match) {
    throw new Error(`Не удалось разобрать: ${label}`);
  }

  return match;
}

function decimal(value) {
  if (value == null || /^[ХX]$/i.test(value)) {
    return null;
  }

  const normalized = value
    .replace(/\s/g, '')
    .replace(',', '.');

  if (!/^-?\d+(?:\.\d+)?$/.test(normalized)) {
    throw new Error(`Не удалось прочитать число: ${value}`);
  }

  return normalized;
}

// Разбираем только первые колонки строки.
// Не используем этот способ для разорванных показаний ОДПУ.
function tokens(input) {
  return input.match(
    /[ХX]|-?\d+(?: \d{3})*(?:,\d+)?/g
  ) ?? [];
}

function cell(values, index, label) {
  if (values[index] === undefined) {
    throw new Error(`Отсутствует поле: ${label}`);
  }

  return decimal(values[index]);
}

function calculationMethod(values, index) {
  const value = cell(values, index, 'способ определения объёма');

  return value === null ? null : Number(value);
}

// Расчётный месяц основной квитанции.
const period = requiredMatch(
  /за\s+(Январь|Февраль|Март|Апрель|Май|Июнь|Июль|Август|Сентябрь|Октябрь|Ноябрь|Декабрь)\s+(\d{4})\s*г\./i,
  'расчётный месяц'
);

const billingMonth =
  `${period[2]}-${months[period[1].toLowerCase()]}`;

// Выделяем таблицу начислений.
const tableStart = flat.indexOf(
  'Содержание ЖИЛОГО помещения и ком. ресурсы'
);

if (tableStart < 0) {
  throw new Error('Не найдено начало таблицы начислений');
}

const tableEnd = flat.indexOf(
  'Итого к оплате за расчетный период',
  tableStart
);

if (tableEnd < 0) {
  throw new Error('Не найден итог таблицы начислений');
}

const table = flat.slice(tableStart, tableEnd);

// Находим заголовки строк вместе с единицами измерения.
// Порядок альтернатив: более длинные названия стоят первыми.
const headingPattern =
  /(Содержание и ремонт жилого помещения|ОИ ХВС для ГВС|ОИ Подогрев воды|ОИ Водоотведение|ОИ Электроэнергия [ТT][123]|ОИ ХВС|Тепловая энергия \(отопление\) по общедомовому прибору учета|Тепловая энергия \(отопление\) по ИПУ|ХВС для нужд ГВС|Холодное водоснабжение|Водоотведение|Электроэнергия:|-\s*полупиковая зона \([ТT]3\)|-\s*ночная зона \([ТT]2\)|-\s*пиковая зона \([ТT]1\)|Подогрев воды)\s+(м2|м3|Гкал|кВтч)\s+/gi;

const headings = [...table.matchAll(headingPattern)];

if (!headings.length) {
  throw new Error('Не найдены строки услуг');
}

const rows = headings.map((match, index) => {
  const start = match.index + match[0].length;
  const end = headings[index + 1]?.index ?? table.length;

  return {
    name: match[1],
    source_unit: match[2],
    values: tokens(table.slice(start, end)),
  };
});

function findRow(pattern, label, required = true) {
  const row = rows.find(item => pattern.test(item.name));

  if (!row && required) {
    throw new Error(`Не найдена строка: ${label}`);
  }

  return row ?? null;
}

// Номера счётчиков берём только из блока поверок.
const verificationBlock =
  flat.match(/Даты поверок ПУ:\s*(.*?)(?:Раздел 5|$)/i)?.[1]
  ?? '';

function meterNumber(pattern) {
  return verificationBlock.match(pattern)?.[1] ?? null;
}

const meters = {
  cold_water: meterNumber(/ХВС\s+(\d+)\s*:/i),
  hot_water: meterNumber(/ХВС для нужд ГВС\s+(\d+)\s*:/i),
  electricity: meterNumber(/Электроэнергия\s+(\d+)\s*:/i),
};

const readings = [];
const charges = [];
const adjustments = [];

// Индивидуальные коммунальные строки:
// объём, способ, ОИ-объём, тариф, плата индивидуальная,
// плата ОИ, начислено, перерасчёт, льготы, пеня,
// к оплате, индивидуальная часть, ОИ-часть,
// норматив, норматив ОИ, показание ИПУ...
function individualCharge(row, service, unit) {
  const v = row.values;

  const charge = {
    source_label: row.name,
    service,
    scope: 'individual',
    zone: null,
    unit,
    consumption: cell(v, 0, `${row.name}: объём`),
    calculation_method_code: calculationMethod(v, 1),
    applied_rate: cell(v, 3, `${row.name}: ставка`),
    amount: cell(v, 6, `${row.name}: начислено`),
    recalculation: cell(v, 7, `${row.name}: перерасчёт`),
    benefit: cell(v, 8, `${row.name}: льготы`),
    penalty: cell(v, 9, `${row.name}: пеня`),
    payable: cell(v, 10, `${row.name}: к оплате`),
  };

  charges.push(charge);

  return charge;
}

// Общее имущество:
// индивидуальный объём, объём ОИ, способ, тариф,
// плата индивидуальная, плата ОИ, начислено,
// перерасчёт, льготы, пеня...
function commonCharge(row, service, unit, zone = null) {
  const v = row.values;

  const charge = {
    source_label: row.name,
    service,
    scope: 'common_property',
    zone,
    unit,
    consumption: cell(v, 1, `${row.name}: объём ОИ`),
    calculation_method_code: calculationMethod(v, 2),
    applied_rate: cell(v, 3, `${row.name}: ставка`),
    amount: cell(v, 6, `${row.name}: начислено`),
    recalculation: cell(v, 7, `${row.name}: перерасчёт`),
    benefit: cell(v, 8, `${row.name}: льготы`),
    penalty: cell(v, 9, `${row.name}: пеня`),
    payable: null,
  };

  charges.push(charge);

  return charge;
}

// Вода и водоотведение.
const waterDefinitions = [
  {
    pattern: /^Холодное водоснабжение$/i,
    service: 'cold_water',
    meter: meters.cold_water,
    has_reading: true,
  },
  {
    pattern: /^ХВС для нужд ГВС$/i,
    service: 'water_for_hot_water',
    meter: meters.hot_water,
    has_reading: true,
  },
  {
    pattern: /^Водоотведение$/i,
    service: 'wastewater',
    meter: null,
    has_reading: false,
  },
];

for (const definition of waterDefinitions) {
  const row = findRow(
    definition.pattern,
    definition.service
  );

  individualCharge(row, definition.service, 'm3');

  if (definition.has_reading) {
    readings.push({
      resource: definition.service,
      meter_number: definition.meter,
      zone: null,
      unit: 'm3',
      previous_value: null,
      current_value: cell(
        row.values,
        15,
        `${row.name}: текущее показание`
      ),
      reading_date: null,
    });
  }
}

// Подогрев воды.
individualCharge(
  findRow(/^Подогрев воды$/i, 'подогрев воды'),
  'water_heating',
  'Gcal'
);

// Отопление: строки могут отсутствовать в другом шаблоне.
const heatingDefinitions = [
  {
    pattern: /^Тепловая энергия \(отопление\) по общедомовому прибору учета$/i,
    service: 'space_heating_building_meter',
  },
  {
    pattern: /^Тепловая энергия \(отопление\) по ИПУ$/i,
    service: 'space_heating_individual_meter',
  },
];

for (const definition of heatingDefinitions) {
  const row = findRow(
    definition.pattern,
    definition.service,
    false
  );

  if (row) {
    individualCharge(row, definition.service, 'Gcal');
  }
}

// Неэлектрические строки общего имущества.
const commonDefinitions = [
  {
    pattern: /^ОИ ХВС$/i,
    service: 'cold_water',
    unit: 'm3',
  },
  {
    pattern: /^ОИ ХВС для ГВС$/i,
    service: 'water_for_hot_water',
    unit: 'm3',
  },
  {
    pattern: /^ОИ Подогрев воды$/i,
    service: 'water_heating',
    unit: 'Gcal',
  },
  {
    pattern: /^ОИ Водоотведение$/i,
    service: 'wastewater',
    unit: 'm3',
  },
];

for (const definition of commonDefinitions) {
  commonCharge(
    findRow(definition.pattern, definition.service),
    definition.service,
    definition.unit
  );
}

// Электроэнергия по зонам.
const zoneDefinitions = [
  { zone: 'T1', label: 'пиковая' },
  { zone: 'T2', label: 'ночная' },
  { zone: 'T3', label: 'полупиковая' },
];

for (const { zone, label } of zoneDefinitions) {
  const digit = zone.slice(1);

  const individual = findRow(
    new RegExp(
      `^-\\s*${label} зона \\([ТT]${digit}\\)$`,
      'i'
    ),
    `электроэнергия ${zone}`
  );

  const v = individual.values;

  charges.push({
    source_label: individual.name,
    service: 'electricity',
    scope: 'individual',
    zone,
    unit: 'kWh',
    consumption: cell(v, 0, `${zone}: расход`),
    calculation_method_code: calculationMethod(v, 1),
    applied_rate: cell(v, 3, `${zone}: ставка`),
    amount: cell(v, 6, `${zone}: начислено`),
    recalculation: cell(v, 7, `${zone}: перерасчёт`),
    benefit: null,
    penalty: null,
    payable: null,
  });

  readings.push({
    resource: 'electricity',
    meter_number: meters.electricity,
    zone,
    unit: 'kWh',
    previous_value: null,
    current_value: cell(v, 15, `${zone}: показание`),
    reading_date: null,
  });

  const common = findRow(
    new RegExp(`^ОИ Электроэнергия [ТT]${digit}$`, 'i'),
    `электроэнергия ОИ ${zone}`
  );

  commonCharge(common, 'electricity', 'kWh', zone);
}

// Электрический итог не включаем повторно в charges.
const electricityTotalRow = findRow(
  /^Электроэнергия:$/i,
  'итог электроэнергии'
);

const electricityTotal = {
  consumption: cell(
    electricityTotalRow.values,
    0,
    'электроэнергия: общий расход'
  ),
  unit: 'kWh',
  amount: cell(
    electricityTotalRow.values,
    6,
    'электроэнергия: общее начисление'
  ),
};

// Содержание жилья.
// Здесь структура отличается от коммунальных строк:
// площадь, Х, ставка, Х, Х, начислено,
// перерасчёт, льготы, пеня, затем объединённый итог.
const maintenance = findRow(
  /^Содержание и ремонт жилого помещения$/i,
  'содержание жилья'
);

charges.push({
  source_label: maintenance.name,
  service: 'housing_maintenance',
  scope: 'housing',
  zone: null,
  unit: 'm2',
  consumption: cell(
    maintenance.values,
    0,
    'содержание жилья: площадь'
  ),
  calculation_method_code: null,
  applied_rate: cell(
    maintenance.values,
    2,
    'содержание жилья: ставка'
  ),
  amount: cell(
    maintenance.values,
    5,
    'содержание жилья: начислено'
  ),
  recalculation: cell(
    maintenance.values,
    6,
    'содержание жилья: перерасчёт'
  ),
  benefit: cell(
    maintenance.values,
    7,
    'содержание жилья: льготы'
  ),
  penalty: cell(
    maintenance.values,
    8,
    'содержание жилья: пеня'
  ),
  payable: null,
});

// Перерасчёт из раздела 5 — детализация,
// а не ещё одна строка начисления.
const section5 = flat.match(
  /Раздел 5 Сведения о перерасчетах.*$/
)?.[0] ?? '';

const maintenanceAdjustment = section5.match(
  /Содержание и ремонт жилого помещения\s+(.+?)\s+(-?\d+(?: \d{3})*,\d{2})(?=\s|$)/
);

if (maintenanceAdjustment) {
  adjustments.push({
    service: 'housing_maintenance',
    scope: 'housing',
    reason: maintenanceAdjustment[1].trim(),
    amount: decimal(maintenanceAdjustment[2]),
    included_in_charge_recalculation: true,
  });
}

// Итоговая строка таблицы.
const totalsMatch = requiredMatch(
  /Итого к оплате за расчетный период\s+(.+?)(?=\s+\*\s*-|$)/i,
  'итоги квитанции'
);

const totalValues = tokens(totalsMatch[1]);

const totals = {
  individual_utilities_amount: cell(
    totalValues, 0, 'итого: индивидуальные коммунальные услуги'
  ),
  common_property_amount: cell(
    totalValues, 1, 'итого: общее имущество'
  ),
  accrued_amount: cell(
    totalValues, 2, 'итого: начислено'
  ),
  recalculation: cell(
    totalValues, 3, 'итого: перерасчёт'
  ),
  benefit: cell(
    totalValues, 4, 'итого: льготы'
  ),
  penalty: cell(
    totalValues, 5, 'итого: пеня'
  ),
  payable: cell(
    totalValues, 6, 'итого: к оплате'
  ),
};

return {
  json: {
    source_filename: sourceFilename,
    source_directory: sourceDirectory,
    source_path: sourcePath,    
    parser_version: 'utility-receipt-v2',
    parsed_scope:
      'utility_charges_meter_readings_adjustments_totals',

    document: {
      billing_month: billingMonth,
      reading_date: null,
      consumption_period_start: null,
      consumption_period_end: null,
      consumption_period_note:
        'В документе объёмы обозначены как относящиеся к предыдущему расчётному месяцу',
      excluded_documents:
        documents.length > 2
          ? ['Последующие платёжные документы, включая страхование']
          : [],
    },

    meter_readings: readings,
    charges,
    adjustments,
    electricity_individual_total: electricityTotal,
    totals,

    parsing_notes: [
      'Предыдущие показания не вычислялись',
      'Точная дата снятия показаний не установлена',
      'Показания общедомовых приборов не извлекались',
      'Итог электроэнергии не дублируется в charges',
      'Перерасчёты раздела 5 являются детализацией',
      'Объединённый итог содержания и ОИ не присвоен одной услуге',
      'Персональные и банковские сведения не включены в результат',
    ],
  },
};

if ($json.status !== 'saved' || !$json.document_id) {
  throw new Error('Нет подтверждения успешного сохранения документа');
}

const filename = $json.source_filename;
const path = $json.source_path;
const directory = '/files/utility-import';

if (
  typeof filename !== 'string' ||
  !filename ||
  filename.includes('/') ||
  filename.includes('\\') ||
  /[\x00-\x1f\x7f]/.test(filename) ||
  !/\.pdf$/i.test(filename)
) {
  throw new Error('Недопустимое имя PDF для удаления');
}

if (path !== `${directory}/${filename}`) {
  throw new Error('Путь файла не соответствует входной папке');
}

// Экранирование аргумента для POSIX shell.
// Имя файла не должно интерпретироваться как команда.
function shellQuote(value) {
  return "'" + value.replace(/'/g, "'\\''") + "'";
}

return {
  json: {
    ...$json,
    delete_command: `rm -- ${shellQuote(path)}`,
  },
};

const item = $input.item;
const filename = item.binary?.data?.fileName;

if (
  typeof filename !== 'string' ||
  !filename ||
  filename.includes('/') ||
  filename.includes('\\') ||
  /[\x00-\x1f\x7f]/.test(filename) ||
  !/\.pdf$/i.test(filename)
) {
  throw new Error('Отсутствует или недопустимо имя PDF');
}

return {
  json: {
    ...item.json,
    source_filename: filename,
    source_directory: '/files/utility-import',
    source_path: `/files/utility-import/${filename}`,
  },
  binary: item.binary,
};
